import re
K=['desc','fn','nerve','blood','rel','clin']
R={
'frontal':["Membentuk dahi, atap rongga mata, dan bagian depan dasar tengkorak; berongga oleh sinus frontalis.","Melindungi lobus frontal otak dan membentuk atap orbita.","N. supraorbitalis dan n. supratrochlearis (cabang V1).","A. supraorbitalis, a. supratrochlearis, cabang a. meningea media.","Os parietale (sutura koronalis), sfenoid, etmoid, nasal, zigomatik, maksila.","Fraktur depresi dahi, sinusitis frontalis, hematoma epidural."],
'parietal':["Tulang pipih persegi yang membentuk atap dan sisi tengkorak.","Melindungi otak; permukaan dalamnya beralur oleh a. meningea media.","Cabang n. trigeminus (V) untuk periosteum dan dura; n. oksipitalis mayor di tepi belakang.","A. meningea media dan a. temporalis superfisialis.","Frontal (sutura koronalis), parietal kontralateral (sagitalis), oksipital (lambdoidea), temporal.","Fraktur parietal dengan hematoma epidural, kraniosinostosis (skafosefali)."],
'occipital':["Membentuk dasar dan belakang tengkorak; memiliki foramen magnum dan kondilus oksipital.","Melindungi serebelum dan batang otak; bersendi dengan atlas (C1).","N. oksipitalis mayor dan minor; n. hipoglosus (XII) lewat kanalis hipoglosi.","A. oksipitalis, a. meningea posterior, a. vertebralis (melalui foramen magnum).","Atlas (sendi atlanto-oksipital), parietal, temporal, sfenoid.","Fraktur basis kranii posterior, herniasi tonsil serebelum, malformasi Chiari."],
'temporal':["Terdiri dari pars skuamosa, petrosa, timpanika, dan mastoid, dengan prosesus stiloideus dan zigomatikus.","Rumah telinga tengah dan dalam, sendi temporomandibular, dan pelindung lobus temporal.","N. fasialis (VII) dan n. vestibulokoklearis (VIII) melalui pars petrosa; n. aurikulotemporalis.","A. temporalis superfisialis, a. aurikularis posterior, a. stilomastoidea, a. meningea media.","Mandibula (TMJ), zigomatik, parietal, oksipital, sfenoid, telinga.","Fraktur os temporale (paresis fasialis, hemotimpanum), mastoiditis, pterion rentan mengenai a. meningea media."],
'sphenoid':["Tulang tengah dasar tengkorak berbentuk kelelawar: korpus, ala mayor dan minor, prosesus pterigoideus, sela tursika.","Menopang hipofisis, membentuk dinding orbita, dan jalur banyak saraf kranial.","N. II (foramen opticum); III, IV, V1, VI (fissura orbitalis superior); V2 (foramen rotundum); V3 (foramen ovale).","A. meningea media (foramen spinosum), cabang a. maksilaris dan a. karotis interna.","Semua tulang kranium, vomer, palatum, zigomatik; sinus kavernosus.","Tumor hipofisis menekan kiasma optikum (hemianopsia bitemporal), fraktur basis kranii, sinusitis sfenoid."],
'ethmoid':["Tulang spons ringan di antara orbita: lamina kribrosa, krista galli, lamina perpendikularis, dan labirin etmoid.","Membentuk bagian atas septum nasi, dinding medial orbita, dan sel udara etmoid.","N. olfaktorius (I) menembus lamina kribrosa; n. etmoidalis anterior dan posterior (V1).","A. etmoidalis anterior dan posterior (cabang a. oftalmika).","Frontal, sfenoid, vomer, maksila, lakrimal, konka inferior.","Fraktur lamina kribrosa (rinore LCS, anosmia), etmoiditis, selulitis orbita."],
'ethcells':["Rongga udara kecil di labirin etmoid (anterior, tengah, posterior).","Meringankan tengkorak dan menghangatkan udara napas; bagian sinus paranasal.","N. etmoidalis anterior dan posterior (V1).","A. etmoidalis anterior dan posterior.","Meatus nasi media (sel anterior dan tengah), meatus superior (posterior); lamina papirasea.","Etmoiditis, penyebaran infeksi ke orbita melalui lamina papirasea."],
'sinus':["Rongga berisi udara berlapis mukosa di dalam tulang (frontal atau sfenoid).","Meringankan tengkorak, resonansi suara, melembabkan udara.","Frontal: n. supraorbitalis (V1); sfenoid: n. etmoidalis posterior dan V2.","Frontal: a. supraorbitalis dan etmoidalis; sfenoid: cabang a. faringea dan etmoidalis posterior.","Sinus frontal bermuara ke meatus media; sinus sfenoid ke resesus sfenoetmoidal.","Sinusitis akut atau kronis, mukokel, komplikasi ke orbita dan otak."],
'nasal':["Dua tulang kecil berbentuk persegi yang membentuk batang hidung.","Menopang jembatan hidung dan melindungi rongga hidung bagian atas.","N. infratrochlearis dan n. etmoidalis anterior (cabang nasal eksternal).","A. dorsalis nasi, a. angularis, a. etmoidalis anterior.","Frontal, maksila (prosesus frontalis), etmoid, tulang rawan septum dan alar.","Fraktur hidung (cedera wajah tersering), deviasi septum."],
'lacrimal':["Tulang tipis seukuran kuku di dinding medial orbita dengan fossa kantung lakrimal.","Membentuk jalur duktus nasolakrimalis.","N. infratrochlearis dan n. lakrimalis (V1).","Cabang a. oftalmika dan a. infraorbitalis.","Maksila, frontal, etmoid (lamina papirasea), konka inferior.","Obstruksi duktus nasolakrimalis, dakriosistitis."],
'maxilla':["Tulang rahang atas berpasangan: korpus (dengan sinus maksilaris), prosesus frontalis, zigomatikus, alveolaris, dan palatinus.","Menopang gigi atas, membentuk dasar orbita, sebagian hidung, dan langit-langit keras.","N. maksilaris (V2): n. infraorbitalis, n. alveolaris superior, n. nasopalatinus.","A. maksilaris (a. infraorbitalis, a. alveolaris superior), a. palatina mayor.","Zigomatik, nasal, frontal, etmoid, palatinum, vomer, konka inferior.","Fraktur Le Fort I–III, sinusitis maksilaris, celah langit-langit."],
'palatine':["Tulang berbentuk L di belakang maksila, dengan lempeng horizontal dan perpendikular.","Membentuk bagian belakang langit-langit keras dan dinding lateral hidung.","N. palatina mayor dan minor (V2).","A. palatina desendens (cabang a. maksilaris), a. sfenopalatina.","Maksila, sfenoid (prosesus pterigoideus), vomer, etmoid.","Celah langit-langit, fraktur Le Fort."],
'zygomatic':["Tulang pipi yang membentuk tonjolan pipi dan sebagian dinding lateral orbita.","Membentuk kontur wajah dan arkus zigomatik; tempat melekat otot masseter.","N. zigomatikofasialis dan zigomatikotemporalis (V2).","A. transversa fasialis, a. zigomatikoorbitalis.","Frontal, maksila, temporal (arkus zigomatik), sfenoid.","Fraktur tripod zigomatikomaksilar, kebas pipi akibat cedera n. infraorbitalis."],
'vomer':["Tulang pipih tipis di garis tengah rongga hidung.","Membentuk bagian bawah belakang septum nasi.","N. nasopalatinus (V2).","A. sfenopalatina (cabang septal posterior), a. etmoidalis.","Etmoid (lamina perpendikularis), sfenoid, maksila, palatinum, tulang rawan septum.","Deviasi septum, epistaksis dari pleksus Kiesselbach."],
'concha':["Tulang melengkung tipis di dinding lateral rongga hidung bagian bawah.","Memperluas permukaan mukosa untuk menghangatkan dan melembabkan udara napas.","N. nasalis posterior inferior (V2), n. palatina mayor.","A. sfenopalatina dan a. palatina desendens.","Maksila, palatinum, lakrimal, etmoid; meatus nasi inferior.","Hipertrofi konka (hidung tersumbat), epistaksis."],
'hyoid':["Tulang berbentuk U di leher, satu-satunya tulang yang tidak bersendi dengan tulang lain.","Menopang lidah dan laring, tempat melekat otot suprahioid dan infrahioid, membantu menelan.","N. hipoglosus (XII), ansa servikalis, n. mandibularis (V3), n. fasialis (VII).","A. lingualis dan a. tiroidea superior.","Laring (membran tirohioid), lidah, mandibula, otot suprahioid dan infrahioid.","Fraktur hioid (sering pada pencekikan), sindrom Eagle."],
'ossicle':["Tulang pendengaran terkecil (maleus, inkus, stapes) di telinga tengah.","Menghantarkan getaran dari membran timpani ke telinga dalam.","N. stapedius (cabang VII), n. tensor timpani (V3), korda timpani (VII).","A. timpanika anterior, a. stilomastoidea, a. timpanika inferior.","Membran timpani, jendela oval, otot stapedius dan tensor timpani.","Otosklerosis (stapes terfiksasi), diskontinuitas osikular, tuli konduktif."],
'vert_c':["Ruas servikal (C3–C7) kecil dengan foramen transversarium dan prosesus spinosus bercabang dua (C3–C6).","Menopang kepala, memberi gerak leher, melindungi medula spinalis dan a. vertebralis.","Rami dorsal dan ventral saraf spinal servikal; pleksus servikalis dan brakialis.","A. vertebralis (melalui foramen transversarium), a. servikalis asendens.","Diskus intervertebralis, ligamen longitudinal, otot leher.","Whiplash, spondilosis servikal, radikulopati, fraktur dan dislokasi faset."],
'vert_t':["Ruas torakal (T1–T12) dengan faset kosta untuk bersendi dengan rusuk dan prosesus spinosus panjang miring ke bawah.","Menopang rongga dada, tempat melekat rusuk, melindungi medula spinalis.","Rami dorsal dan ventral saraf spinal torakal (n. interkostalis).","A. interkostalis posterior dan a. subkostalis.","Rusuk (sendi kostovertebral), diskus, otot erector spinae.","Fraktur kompresi osteoporotik, skoliosis, kifosis (penyakit Scheuermann)."],
'vert_l':["Ruas lumbal (L1–L5) terbesar dengan korpus tebal dan prosesus mamilar.","Menahan beban terbesar tubuh bagian atas; memungkinkan fleksi-ekstensi batang tubuh.","Rami dorsal dan ventral saraf spinal lumbal (pleksus lumbalis).","A. lumbalis dan a. iliolumbalis.","Diskus intervertebralis, sakrum (L5–S1), otot psoas, ligamen iliolumbal.","HNP L4–L5 dan L5–S1, stenosis kanalis, spondilolistesis, nyeri punggung bawah."],
'atlas':["Vertebra C1 berbentuk cincin tanpa korpus, dengan massa lateral dan arkus anterior dan posterior.","Menopang tengkorak (sendi atlanto-oksipital, gerak mengangguk).","N. suboksipitalis (ramus dorsal C1).","A. vertebralis (melingkar di sulkus arteri vertebralis).","Tulang oksipital, aksis (dens), ligamen transversum atlantis.","Fraktur Jefferson, instabilitas atlantoaksial (misalnya pada artritis reumatoid)."],
'axis':["Vertebra C2 dengan dens (prosesus odontoideus) yang menonjol ke atas.","Poros rotasi kepala (menggeleng) bersama atlas.","N. oksipitalis mayor (ramus dorsal C2).","A. vertebralis dan a. servikalis profunda.","Atlas (sendi atlantoaksial median), ligamen alar dan apikal, vertebra C3.","Fraktur dens, fraktur hangman (spondilolistesis traumatik C2)."],
'sacrum':["Lima vertebra sakral menyatu membentuk tulang segitiga di belakang panggul.","Menyalurkan beban tulang belakang ke panggul dan membentuk dinding belakang rongga pelvis.","Rami ventral dan dorsal S1–S4 melalui foramen sakral; pleksus sakralis.","A. sakralis lateralis dan mediana, a. iliolumbalis.","L5, koksigis, tulang panggul (sendi sakroiliaka).","Nyeri sendi sakroiliaka, fraktur sakrum (cedera saraf), spina bifida okulta."],
'coccyx':["Tiga hingga lima vertebra koksigeal kecil menyatu di ujung kolumna vertebralis.","Tempat melekat otot dasar panggul dan ligamen; menopang saat duduk condong ke belakang.","N. anokoksigeus (S4–S5, Co1).","A. sakralis mediana dan a. glutea inferior.","Sakrum (sendi sakrokoksigeal), levator ani, gluteus maksimus.","Koksidinia (nyeri tulang ekor), fraktur akibat jatuh terduduk."],
'rib_typ':["Rusuk tipikal (ke-3 sampai 9) dengan kaput, kolum, tuberkel, angulus, dan korpus beralur kostal.","Membentuk sangkar toraks, melindungi organ dada, dan menggerakkan napas.","N. interkostalis (ramus ventral T3–T9).","A. interkostalis posterior dan anterior (a. torakika interna).","Vertebra torakal (sendi kostovertebral), kartilago kosta, otot interkostal, pleura.","Fraktur rusuk (tersering rusuk 4–9), flail chest, pneumotoraks."],
'rib_atyp':["Rusuk atipikal (ke-1, 2, 10, 11, 12): bentuk khas, rusuk 11–12 melayang; rusuk 1 pipih dengan alur a. subklavia.","Melindungi puncak paru (rusuk 1), tempat melekat otot skalenus dan serratus.","N. interkostalis; di dekat rusuk 1 melintas akar C8–T1 pleksus brakialis.","A. interkostalis suprema (rusuk 1–2), a. interkostalis posterior, a. subkostalis (rusuk 12).","Vertebra torakal, otot skalenus, serratus anterior, diafragma, ginjal (rusuk 11–12).","Fraktur rusuk 1 (trauma berat, risiko cedera pembuluh), rusuk servikal, sindrom outlet toraks."],
'costcart':["Tulang rawan hialin yang menghubungkan ujung depan rusuk ke sternum atau ke tulang rawan di atasnya.","Memberi kelenturan dinding dada saat bernapas.","N. interkostalis (T1–T11).","A. torakika interna dan a. interkostalis anterior.","Rusuk, sternum (rusuk 1–7), tulang rawan rusuk di atasnya (8–10).","Kostokondritis (sindrom Tietze), subluksasi kostokondral."],
'scaphoid':["Karpal terbesar baris proksimal, berbentuk perahu, di sisi radial pergelangan.","Menghubungkan baris karpal proksimal dan distal, menopang gerak pergelangan.","N. medianus dan n. radialis (cabang interoseus).","A. radialis (cabang karpal dorsal dan palmar), aliran masuk dari distal.","Radius, lunatum, kapitatum, trapezium, trapezoid; dasar anatomical snuffbox.","Fraktur skafoid (karpal tersering patah), risiko nekrosis avaskular kutub proksimal."],
'lunate':["Karpal berbentuk bulan sabit di tengah baris proksimal.","Menyalurkan gaya dari kapitatum ke radius.","N. interoseus anterior (medianus) dan posterior (radialis).","Cabang volar dan dorsal a. radialis, a. ulnaris, a. interoseus anterior.","Radius, skafoid, triketrum, kapitatum, hamatum.","Dislokasi lunatum (menekan n. medianus), penyakit Kienböck (nekrosis avaskular)."],
'triquetrum':["Karpal berbentuk piramida di sisi ulnar baris proksimal.","Menahan gaya ulnar pergelangan dan bersendi dengan pisiformis.","N. ulnaris (ramus dorsal) dan n. interoseus posterior.","A. ulnaris, a. interoseus anterior, cabang karpal dorsal.","Lunatum, pisiformis, hamatum, kompleks fibrokartilago triangularis.","Fraktur avulsi dorsal triketrum (jatuh dengan tangan terentang)."],
'pisiform':["Tulang sesamoid kecil berbentuk kacang polong di tendon fleksor karpi ulnaris.","Menambah daya ungkit fleksor karpi ulnaris dan membentuk dinding kanalis Guyon.","N. ulnaris (ramus profundus).","A. ulnaris.","Triketrum, hamatum (ligamen pisohamatum), tendon fleksor karpi ulnaris.","Fraktur pisiformis, neuropati ulnaris di kanalis Guyon."],
'trapezium':["Karpal baris distal sisi radial yang bersendi dengan metakarpal 1 (sendi pelana).","Memungkinkan gerak ibu jari, terutama oposisi.","N. medianus (cabang tenar) dan n. radialis superfisialis.","A. radialis (cabang karpal palmar dan dorsal).","Metakarpal 1 dan 2, skafoid, trapezoid; tuberkel untuk retinakulum fleksor.","Osteoartritis sendi karpometakarpal 1, fraktur trapezium."],
'trapezoid':["Karpal kecil berbentuk baji di baris distal, antara trapezium dan kapitatum.","Menopang metakarpal 2 dan menstabilkan pergelangan.","N. interoseus posterior dan n. medianus.","Cabang karpal dorsal dan palmar a. radialis.","Metakarpal 2, trapezium, kapitatum, skafoid.","Cedera terisolasi jarang; nyeri dasar jari telunjuk setelah trauma."],
'capitate':["Karpal terbesar, di tengah baris distal, dengan kaput yang bersendi dengan lunatum.","Poros mekanik pergelangan dan menopang metakarpal 3.","N. interoseus posterior (radialis) dan cabang profunda n. ulnaris.","A. radialis dan a. interoseus anterior (cabang karpal).","Lunatum, skafoid, hamatum, trapezoid, metakarpal 2–4.","Fraktur kapitatum (kutub proksimal berisiko nekrosis avaskular), dislokasi perilunat."],
'hamate':["Karpal baji di sisi ulnar baris distal dengan hamulus (kait) di sisi palmar.","Menopang metakarpal 4–5; membentuk dinding kanalis Guyon dan terowongan karpal.","Ramus profundus n. ulnaris (berjalan dekat hamulus).","A. ulnaris (cabang profunda).","Triketrum, kapitatum, metakarpal 4–5, pisiformis (via ligamen).","Fraktur hamulus (olahraga raket dan golf), cedera ramus profundus ulnaris."],
'metacarpal':["Lima tulang panjang telapak tangan dengan basis, korpus, dan kaput.","Membentuk kerangka telapak tangan dan titik tumpu genggaman.","N. medianus (sisi radial) dan n. ulnaris (jari 4–5, otot interosei).","Arkus palmaris profunda dan superfisialis, aa. metakarpalis.","Karpal distal, falang proksimal (sendi MCP), otot interosei dan lumbrikal.","Fraktur boxer (metakarpal 5), fraktur Bennett (basis metakarpal 1)."],
'phal_hand':["Tulang jari tangan: proksimal, tengah (tidak ada pada ibu jari), dan distal.","Memungkinkan fleksi, ekstensi jari, dan genggaman halus.","Nn. digitales palmares proprii (n. medianus dan n. ulnaris).","Aa. digitales palmares proprii dari arkus palmaris.","Metakarpal (sendi MCP), sendi PIP dan DIP, tendon fleksor dan ekstensor.","Fraktur falang, mallet finger, dislokasi PIP, trigger finger."],
'talus':["Tulang yang bersendi dengan tibia dan fibula, tanpa perlekatan otot dan hampir seluruhnya tertutup tulang rawan.","Menyalurkan berat badan dari tungkai bawah ke kaki.","N. tibialis dan n. peroneus profundus.","A. tibialis posterior dan a. dorsalis pedis; suplai darah terbatas.","Tibia, fibula (mortise), kalkaneus, navikular.","Fraktur kolum talus (nekrosis avaskular), cedera pergelangan kaki."],
'calcaneus':["Tulang terbesar kaki yang membentuk tumit; sustentakulum tali menopang talus.","Menopang berat badan saat berdiri dan tempat melekat tendon Achilles.","N. plantaris medialis dan lateralis, n. suralis.","A. tibialis posterior (cabang kalkaneus) dan a. peronea.","Talus, kuboid, tendon Achilles, fasia plantaris.","Fraktur kalkaneus (jatuh dari ketinggian), fasciitis plantaris (taji tumit), penyakit Sever."],
'navicular':["Tulang berbentuk perahu di sisi medial kaki, di depan talus.","Menopang lengkung longitudinal medial dan kepala talus.","N. tibialis dan n. peroneus profundus.","A. dorsalis pedis dan a. plantaris medialis.","Talus, tiga kuneiformis, kuboid, tendon tibialis posterior.","Fraktur stres navikular (atlet), sindrom navikular aksesori."],
'cuboid':["Tulang kuboid di sisi lateral kaki dengan alur untuk tendon peroneus longus.","Menopang lengkung lateral dan metatarsal 4–5.","N. plantaris lateralis dan n. suralis.","A. plantaris lateralis dan a. tarsalis lateralis.","Kalkaneus, navikular, kuneiformis lateral, metatarsal 4–5.","Sindrom kuboid (nyeri sisi lateral), fraktur kuboid."],
'cuneiform':["Tiga tulang baji (medial, intermedial, lateral) di depan navikular.","Membentuk lengkung transversal kaki dan menopang metatarsal 1–3.","N. peroneus profundus dan n. plantaris medialis dan lateralis.","A. dorsalis pedis dan a. plantaris medialis.","Navikular, metatarsal 1–3, kuboid; tendon tibialis anterior dan posterior.","Cedera Lisfranc (sendi tarsometatarsal), pes planus."],
'metatarsal':["Lima tulang panjang telapak kaki dengan basis, korpus, dan kaput.","Membentuk lengkung depan kaki dan tumpuan saat mendorong tubuh berjalan.","N. plantaris medialis dan lateralis, n. peroneus profundus.","Arkus plantaris, a. metatarsalis dorsalis dan plantaris.","Tarsal distal, falang proksimal (sendi MTP), otot interosei.","Fraktur Jones (basis metatarsal 5), fraktur stres (march fracture), hallux valgus."],
'phal_foot':["Tulang jari kaki; ibu jari hanya memiliki dua ruas (proksimal dan distal).","Membantu keseimbangan dan dorongan saat melangkah.","N. digitalis plantaris proprius (n. plantaris medialis dan lateralis).","A. digitalis plantaris dan dorsalis.","Metatarsal (sendi MTP), sendi interfalangeal, tendon fleksor dan ekstensor.","Fraktur falang (stub toe), hammertoe, kuku tumbuh ke dalam."],
'sesamoid_foot':["Dua tulang sesamoid kecil di bawah kaput metatarsal 1, dalam tendon fleksor hallucis brevis.","Menyerap tekanan di bawah pangkal ibu jari kaki dan menambah daya ungkit.","N. plantaris medialis (n. digitalis plantaris proprius).","A. plantaris medialis dan arkus plantaris.","Metatarsal 1, tendon fleksor hallucis brevis, ligamen plantar.","Sesamoiditis, fraktur sesamoid, turf toe."],
'incisor':["Gigi depan berbentuk pahat untuk memotong makanan.","Memotong makanan dan membantu pengucapan.","Atas: n. alveolaris superior anterior (V2); bawah: n. alveolaris inferior (V3).","A. alveolaris superior anterior; a. alveolaris inferior.","Gingiva, tulang alveolar, ligamen periodontal, bibir.","Karies, trauma gigi depan, avulsi."],
'canine':["Gigi taring runcing dengan akar terpanjang.","Merobek makanan dan menopang sudut mulut.","N. alveolaris superior anterior (V2); n. alveolaris inferior (V3).","A. alveolaris superior anterior; a. alveolaris inferior.","Gingiva, tulang alveolar, ligamen periodontal.","Impaksi taring atas, abses periapikal."],
'premolar':["Gigi geraham kecil dengan dua kuspid.","Menyobek dan menggiling makanan.","N. alveolaris superior media (V2); n. alveolaris inferior (V3).","A. alveolaris superior; a. alveolaris inferior.","Gingiva, tulang alveolar, sinus maksilaris (gigi atas).","Karies, ekstraksi untuk ortodonti, fraktur kuspid."],
'molar':["Gigi geraham besar dengan 4–5 kuspid dan 2–3 akar.","Menggiling makanan.","N. alveolaris superior posterior (V2); n. alveolaris inferior (V3).","A. alveolaris superior posterior; a. alveolaris inferior.","Gingiva, sinus maksilaris (akar atas), kanalis mandibularis (akar bawah).","Karies, pulpitis, abses, perikoronitis (molar ketiga)."],
'larynx_cart':["Tulang rawan laring (tiroid, krikoid, aritenoid, kornikulata) yang menyusun kerangka laring.","Melindungi jalan napas dan mengatur pita suara untuk fonasi.","N. laringeus superior dan n. laringeus rekuren (cabang vagus X).","A. tiroidea superior dan inferior (a. laringea).","Hioid, trakea, otot intrinsik laring, pita suara.","Fraktur laring, intubasi sulit, cedera n. laringeus rekuren (suara serak)."],
'nasal_cart':["Tulang rawan hialin penopang hidung (septum, alar mayor, prosesus lateral).","Menjaga bentuk hidung dan lubang hidung tetap terbuka.","N. etmoidalis anterior dan n. infraorbitalis.","A. labialis superior, a. dorsalis nasi, a. etmoidalis anterior.","Tulang hidung, maksila, vomer, etmoid.","Hematoma septum, deviasi septum, rinoplasti."],
}
